const HERO_CAR_ID = 11; // 2024 BMW X6 M Competition — single static hero photo
const MOST_VIEWED_IDS = [1, 2, 4, 5, 6, 11, 9, 18, 19, 81, 79, 85, 99, 98, 71, 46, 183, 156, 123, 77];

function getCarById(id) {
  return CARS.find(c => c.id === id);
}
function getHeroCar() {
  return getCarById(HERO_CAR_ID);
}
function getMostViewedCars() {
  return MOST_VIEWED_IDS.map(getCarById).filter(Boolean);
}
